          <ul class="mt-xs ml-md list-disc">
            @for (err of store.error()!.split("\\n"); track err) {
              <li>{{ err }}</li>
            }
          </ul>
        </div>
      }

      <div class="grid grid-cols-2 gap-md">
        <tfc-scenario-event-editor />
        <tfc-scenario-issue-editor />

        <ui-card [title]="domain.term('decision') + ' Templates'">
          @for (dt of store.content().decision_templates; track dt.id) {
            <div class="flex flex-col gap-xs p-sm border-b">
              @if (editingDtId() === dt.id) {
                <div class="flex flex-col gap-xs">
                  <ui-input
                    id="edit-dt-title"
                    label="Title"
                    [value]="editDtTitle()"
                    (valueChange)="editDtTitle.set($event)"
                  />
                  <ui-input
                    id="edit-dt-desc"
                    label="Description"
                    [value]="editDtDesc()"
                    (valueChange)="editDtDesc.set($event)"
                  />
                  <div class="flex gap-sm">
                    <ui-input
                      id="edit-dt-issue"
                      label="Issue ID"
                      [value]="editDtIssueId()"
                      (valueChange)="editDtIssueId.set($event)"
                    />
                    <div class="flex flex-col gap-xs" style="flex:1">
                      <label class="text-xs">Question Type</label>
                      <select
                        class="input-base"
                        [value]="editDtQType()"
                        (change)="editDtQType.set(sel($event))"
                      >
                        <option value="single_choice">Single Choice</option>
                        <option value="multi_choice">Multi Choice</option>
                        <option value="free_text">Free Text</option>
                      </select>
                    </div>
                  </div>
                  <div class="flex gap-sm">
                    <button
                      uiButton
                      variant="default"
                      size="sm"
                      (click)="saveDt(dt.id)"
                    >
                      Save
                    </button>
                    <button
                      uiButton
                      variant="outline"
                      size="sm"
                      (click)="editingDtId.set(null)"
