import { DomainService } from "../../core/domain.service";
import type { DecisionTemplateDef } from "../../core/scenario-api.service";
import { ScenarioBuilderStore } from "./scenario-builder.store";

@Component({
  selector: "tfc-scenario-decision-editor",
