    addDecisionTemplate: vi.fn(),
    removeDecisionTemplate: vi.fn(),
    updateDecisionTemplate: vi.fn(),
  };

  const mockDomain = {
    term: vi.fn().mockReturnValue("Decision"),
  };

  beforeEach(async () => {
    vi.clearAllMocks();
    mockStore.content = signal(emptyContent);

    await TestBed.configureTestingModule({
