    expect(mockStore.addDecisionTemplate).toHaveBeenCalledWith(
      expect.objectContaining({
        title: "New Decision",
        issue_id: "iss-5",
        question_type: "single_choice",
        options: [],
        completion_mode: "first_response",
      }),
