    const removeBtn = Array.from(el.querySelectorAll("button")).find(
      (b) => b.textContent?.trim() === "Remove",
    );
    removeBtn!.click();
    fixture.detectChanges();

    expect(mockStore.removeDecisionTemplate).toHaveBeenCalledWith("dt-1");
  });
});

