14→  changeDetection: ChangeDetectionStrategy.OnPush,
15→  imports: [CardComponent, ButtonDirective, BadgeComponent],
16→  template: `
17→    @if (sortedEvents().length === 0) {
18→      <div class="flex items-center justify-center p-2xl">
19→        <p class="text-muted-foreground">No events to walk through.</p>
20→      </div>
21→    } @else {
22→      <div class="flex flex-col items-center gap-lg p-lg" style="max-width: 40rem; margin: 0 auto">
23→        @let event = sortedEvents()[safeIndex()];
24→        <ui-card [title]="event.title" style="width: 100%">
25→          <div class="flex flex-col gap-sm p-sm">
26→            <div class="flex gap-sm items-center">
27→              <ui-badge variant="secondary">{{ event.event_type }}</ui-badge>
28→              <span class="text-sm text-muted-foreground">{{ formatTime(event.scheduled_pt_ms) }}</span>
29→              @if (event.duration_ms) {
30→                <span class="text-xs text-muted-foreground">duration: {{ formatTime(event.duration_ms) }}</span>
31→              }
32→            </div>
33→            @if (event.description) {
34→              <p class="text-sm">{{ event.description }}</p>
35→            }
36→            @if (event.target_roles.length > 0) {
37→              <div class="flex gap-xs items-center">
38→                <span class="text-xs text-muted-foreground">Roles:</span>
39→                @for (role of event.target_roles; track role) {
40→                  <ui-badge variant="outline">{{ role }}</ui-badge>
41→                }
42→              </div>
43→            }
44→            @if (event.triggered_issues.length > 0) {
45→              <div class="flex gap-xs items-center">
46→                <span class="text-xs text-muted-foreground">Triggers:</span>
47→                @for (issueId of event.triggered_issues; track issueId) {
48→                  <ui-badge variant="outline">{{ issueId }}</ui-badge>
49→                }
50→              </div>
51→            }
52→          </div>
53→        </ui-card>
54→
55→        <div class="flex items-center gap-md">
56→          <button
57→            uiButton
58→            variant="outline"
59→            [disabled]="safeIndex() === 0"
60→            (click)="currentIndex.set(safeIndex() - 1)"
61→          >Previous</button>
62→          <span class="text-sm text-muted-foreground">
63→            Event {{ safeIndex() + 1 }} of {{ sortedEvents().length }}
64→            — {{ formatTime(event.scheduled_pt_ms) }}
65→          </span>
66→          <button
67→            uiButton
68→            variant="outline"
69→            [disabled]="safeIndex() >= sortedEvents().length - 1"
70→            (click)="currentIndex.set(safeIndex() + 1)"
71→          >Next</button>
72→        </div>
73→      </div>
74→    }
75→  `,
76→})
77→export class ScenarioWalkthroughComponent {
78→  private readonly store = inject(ScenarioBuilderStore);
79→
80→  protected readonly sortedEvents = computed(() =>
81→    [...this.store.content().events].sort(
82→      (a, b) => a.scheduled_pt_ms - b.scheduled_pt_ms,
83→    ),
84→  );
85→
86→  protected readonly currentIndex = signal(0);
87→
88→  protected readonly safeIndex = computed(() => {
89→    const len = this.sortedEvents().length;
90→    if (len === 0) return 0;
91→    return Math.min(this.currentIndex(), len - 1);
92→  });
93→
94→  protected formatTime(ms: number): string {
95→    return formatTimeMs(ms);
96→  }
97→}
