 10→interface ScenarioBuilderState {
 11→  scenarioId: number | null;
 12→  title: string;
 13→  description: string;
 14→  content: ScenarioContent;
 15→  saving: boolean;
 16→  error: string | null;
 17→  loadedSnapshot: string | null;
 18→}
 19→
 20→const emptyContent: ScenarioContent = {
 21→  phases: [],
 22→  events: [],
 23→  issues: [],
 24→  decision_templates: [],
 25→  default_time_factor: 1.0,
 26→  briefing: "",
 27→  objectives: [],
 28→  rules: [],
 29→  roles: [],
 30→  game_mode: "classic",
 31→  turns: [],
 32→  initial_system_states: [],
 33→};
 34→
 35→export const ScenarioBuilderStore = signalStore(
 36→  withState<ScenarioBuilderState>({
 37→    scenarioId: null,
 38→    title: "",
 39→    description: "",
 40→    content: emptyContent,
 41→    saving: false,
 42→    error: null,
 43→    loadedSnapshot: null,
 44→  }),
 45→
 46→  withMethods((store) => ({
 47→    loadScenario(
 48→      id: number,
 49→      title: string,
 50→      description: string,
 51→      content: ScenarioContent | null,
 52→    ): void {
 53→      const c = content ?? emptyContent;
 54→      const snapshot = JSON.stringify({ title, description, content: c });
 55→      patchState(store, {
 56→        scenarioId: id,
 57→        title,
 58→        description,
 59→        content: c,
 60→        loadedSnapshot: snapshot,
 61→      });
 62→    },
 63→
 64→    loadImport(
 65→      title: string,
 66→      description: string,
 67→      content: ScenarioContent,
 68→    ): void {
 69→      patchState(store, {
 70→        scenarioId: null,
 71→        title,
 72→        description,
 73→        content,
 74→        loadedSnapshot: null,
 75→        error: null,
 76→      });
 77→    },
 78→
 79→    revert(): void {
 80→      const snap = store.loadedSnapshot();
 81→      if (!snap) return;
 82→      const { title, description, content } = JSON.parse(snap) as {
 83→        title: string;
 84→        description: string;
 85→        content: ScenarioContent;
 86→      };
 87→      patchState(store, { title, description, content });
 88→    },
 89→
 90→    setTitle(title: string): void {
 91→      patchState(store, { title });
 92→    },
 93→
 94→    setDescription(description: string): void {
 95→      patchState(store, { description });
 96→    },
 97→
 98→    setTimeFactor(factor: number): void {
 99→      patchState(store, {
100→        content: { ...store.content(), default_time_factor: factor },
101→      });
102→    },
103→
104→    addEvent(event: ScenarioEventDef): void {
105→      patchState(store, {
106→        content: {
107→          ...store.content(),
108→          events: [...store.content().events, event],
109→        },
110→      });
111→    },
112→
113→    removeEvent(eventId: string): void {
114→      patchState(store, {
115→        content: {
116→          ...store.content(),
117→          events: store.content().events.filter((e) => e.id !== eventId),
118→        },
119→      });
120→    },
121→
122→    updateEvent(eventId: string, updates: Partial<ScenarioEventDef>): void {
123→      patchState(store, {
124→        content: {
125→          ...store.content(),
126→          events: store
127→            .content()
128→            .events.map((e) => (e.id === eventId ? { ...e, ...updates } : e)),
129→        },
130→      });
131→    },
132→
133→    addIssue(issue: ScenarioIssueDef): void {
134→      patchState(store, {
135→        content: {
136→          ...store.content(),
137→          issues: [...store.content().issues, issue],
138→        },
139→      });
140→    },
141→
142→    removeIssue(issueId: string): void {
143→      patchState(store, {
144→        content: {
145→          ...store.content(),
146→          issues: store.content().issues.filter((i) => i.id !== issueId),
147→        },
148→      });
149→    },
150→
151→    updateIssue(issueId: string, updates: Partial<ScenarioIssueDef>): void {
152→      patchState(store, {
153→        content: {
154→          ...store.content(),
155→          issues: store
156→            .content()
157→            .issues.map((i) => (i.id === issueId ? { ...i, ...updates } : i)),
158→        },
159→      });
160→    },
161→
162→    addDecisionTemplate(template: DecisionTemplateDef): void {
163→      patchState(store, {
164→        content: {
165→          ...store.content(),
166→          decision_templates: [...store.content().decision_templates, template],
167→        },
168→      });
169→    },
170→
171→    removeDecisionTemplate(templateId: string): void {
172→      patchState(store, {
173→        content: {
174→          ...store.content(),
175→          decision_templates: store
176→            .content()
177→            .decision_templates.filter((d) => d.id !== templateId),
178→        },
179→      });
180→    },
181→
182→    updateDecisionTemplate(
183→      templateId: string,
184→      updates: Partial<DecisionTemplateDef>,
185→    ): void {
186→      patchState(store, {
187→        content: {
188→          ...store.content(),
189→          decision_templates: store
190→            .content()
191→            .decision_templates.map((d) =>
192→              d.id === templateId ? { ...d, ...updates } : d,
193→            ),
194→        },
195→      });
196→    },
197→
198→    addRole(role: RoleDef): void {
199→      patchState(store, {
200→        content: {
201→          ...store.content(),
202→          roles: [...(store.content().roles ?? []), role],
203→        },
204→      });
205→    },
206→
207→    removeRole(roleId: string): void {
208→      patchState(store, {
209→        content: {
210→          ...store.content(),
211→          roles: (store.content().roles ?? []).filter((r) => r.id !== roleId),
212→        },
213→      });
