116→export class ScenarioBuilderView implements OnInit {
117→  protected readonly store = inject(ScenarioBuilderStore);
118→  private readonly api = inject(ScenarioApiService);
119→  protected readonly scenarios = signal<{ id: number; title: string }[]>([]);
120→
121→  protected readonly viewMode = signal<"global" | "walkthrough">("global");
122→
123→  protected readonly isDirty = computed(() => {
124→    const snap = this.store.loadedSnapshot();
125→    if (!snap) return false;
126→    const current = JSON.stringify({
127→      title: this.store.title(),
128→      description: this.store.description(),
129→      content: this.store.content(),
130→    });
131→    return current !== snap;
132→  });
133→
134→  protected readonly sidebarSections = computed<SidebarSection[]>(() => {
135→    const c = this.store.content();
136→    return [
137→      { id: "roles", label: "Roles", count: (c.roles ?? []).length },
138→      { id: "events", label: "Events", count: c.events.length },
139→      { id: "issues", label: "Issues", count: c.issues.length },
140→      { id: "decisions", label: "Decisions", count: c.decision_templates.length },
141→      { id: "turns", label: "Turns", count: (c.turns ?? []).length },
142→      { id: "settings", label: "Settings", count: 0 },
143→    ];
144→  });
145→
146→  ngOnInit(): void {
147→    this.loadList();
148→  }
149→
150→  private loadList(): void {
151→    this.api.list().subscribe({
152→      next: (list) => this.scenarios.set(list.map((s) => ({ id: s.id, title: s.title }))),
153→    });
154→  }
155→
156→  protected loadScenario(id: number): void {
157→    this.api.get(id).subscribe({
158→      next: (s) => this.store.loadScenario(s.id, s.title, s.description, s.content),
159→    });
160→  }
161→
162→  protected save(): void {
163→    this.store.clearError();
164→    const content = this.store.content();
165→    const errors = validateScenarioContent(content);
166→    if (!this.store.title().trim()) errors.unshift("Title is required.");
167→    if (errors.length > 0) {
168→      this.store.setError(errors.join("\n"));
169→      return;
170→    }
171→    this.store.setSaving(true);
172→    const payload = { title: this.store.title(), description: this.store.description(), content };
173→    const id = this.store.scenarioId();
174→    const req = id ? this.api.update(id, payload) : this.api.create(payload);
175→    req.subscribe({
176→      next: (s) => {
177→        this.store.loadScenario(s.id, s.title, s.description, s.content);
178→        this.store.setSaving(false);
179→        this.loadList();
180→      },
181→      error: () => this.store.setError("Save failed — server rejected the scenario."),
182→    });
183→  }
184→
185→  protected saveAsCopy(): void {
186→    const id = this.store.scenarioId();
187→    if (!id) return;
188→    this.store.setSaving(true);
189→    this.api.clone(id).subscribe({
190→      next: (s) => {
191→        this.store.loadScenario(s.id, s.title, s.description, s.content);
192→        this.store.setSaving(false);
193→        this.loadList();
194→      },
195→      error: () => {
196→        this.store.setSaving(false);
197→        this.store.setError("Clone failed.");
198→      },
199→    });
200→  }
201→
202→  protected deleteScenario(id: number): void {
203→    this.api.delete(id).subscribe({ next: () => this.loadList() });
204→  }
205→}
