192→              d.id === templateId ? { ...d, ...updates } : d,
193→            ),
194→        },
195→      });
196→    },
197→
198→    addRole(role: RoleDef): void {
199→      patchState(store, {
200→        content: {
201→          ...store.content(),
202→          roles: [...(store.content().roles ?? []), role],
203→        },
204→      });
205→    },
206→
207→    removeRole(roleId: string): void {
208→      patchState(store, {
209→        content: {
210→          ...store.content(),
211→          roles: (store.content().roles ?? []).filter((r) => r.id !== roleId),
212→        },
213→      });
214→    },
215→
216→    updateRole(roleId: string, updates: Partial<RoleDef>): void {
217→      patchState(store, {
218→        content: {
219→          ...store.content(),
220→          roles: (store.content().roles ?? []).map((r) =>
221→            r.id === roleId ? { ...r, ...updates } : r,
222→          ),
223→        },
224→      });
225→    },
226→
227→    setBriefing(briefing: string): void {
228→      patchState(store, {
229→        content: { ...store.content(), briefing },
230→      });
231→    },
232→
233→    setSaving(saving: boolean): void {
234→      patchState(store, { saving });
235→    },
236→
237→    setError(error: string): void {
238→      patchState(store, { error, saving: false });
239→    },
240→
241→    clearError(): void {
242→      patchState(store, { error: null });
243→    },
244→
245→    reset(): void {
246→      patchState(store, {
247→        scenarioId: null,
248→        title: "",
249→        description: "",
250→        content: emptyContent,
251→        saving: false,
252→        error: null,
253→        loadedSnapshot: null,
254→      });
255→    },
256→  })),
257→);
