  1→/**
  2→ * fast-check arbitraries for player view state dimensions.
  3→ *
  4→ * Generates valid { snapshot, context, role, participantId, practiceMode }
  5→ * tuples covering the full player view state space:
  6→ *   phase × score × events × issues × decisions × role × systems × practiceMode
  7→ */
  8→import fc from "fast-check";
  9→
 10→// ── Primitive arbitraries ────────────────────────────────────────────
 11→
 12→export const phaseArb = fc.constantFrom(
 13→  "setup",
 14→  "briefing",
 15→  "running",
 16→  "paused",
 17→  "completed",
 18→);
 19→
 20→export const roleArb = fc.constantFrom("co", "nav", "ops");
 21→
 22→// ── Score ────────────────────────────────────────────────────────────
 23→
 24→const scoreRecordArb = fc.record({
 25→  total_score: fc.double({ min: -50, max: 200, noNaN: true, noDefaultInfinity: true }),
 26→  stress: fc.integer({ min: 0, max: 10 }),
 27→  turn_number: fc.integer({ min: 1, max: 15 }),
 28→  next_decision_time_ms: fc.integer({ min: 0, max: 600_000 }),
 29→});
 30→
 31→export type Score = {
 32→  total_score: number;
 33→  stress: number;
 34→  turn_number: number;
 35→  next_decision_time_ms: number;
 36→};
 37→
 38→// ── Events ───────────────────────────────────────────────────────────
 39→
 40→const eventLifecycleArb = fc.constantFrom("scheduled", "running", "completed");
 41→
 42→let eventCounter = 0;
 43→
 44→const eventArb = eventLifecycleArb.chain((lifecycle) => {
 45→  const id = `e-${++eventCounter}`;
 46→  const basePtMs = fc.integer({ min: 1_000, max: 500_000 });
 47→
 48→  return basePtMs.map((pt) => ({
 49→    id,
 50→    title: `Event ${id}`,
 51→    description: `Description for ${id}`,
 52→    event_type: "narrative" as const,
 53→    scheduled_pt_ms: pt,
 54→    duration_ms: lifecycle === "completed" ? 5_000 : null,
 55→    dependencies: [] as string[],
 56→    lifecycle,
 57→    started_at_pt_ms: lifecycle === "scheduled" ? null : pt,
 58→    completed_at_pt_ms: lifecycle === "completed" ? pt + 5_000 : null,
 59→  }));
 60→});
 61→
 62→export const eventsArb = fc.array(eventArb, { maxLength: 3 });
 63→
 64→export type MockEvent = ReturnType<typeof eventArb extends fc.Arbitrary<infer T> ? () => T : never>;
 65→
 66→// ── Issues ───────────────────────────────────────────────────────────
 67→
 68→const issueLifecycleArb = fc.constantFrom("active", "mitigated", "resolved");
 69→
 70→let issueCounter = 0;
 71→
 72→const issueArb = fc.record({
 73→  lifecycle: issueLifecycleArb,
 74→  released: fc.boolean(),
 75→}).map(({ lifecycle, released }) => {
 76→  const id = `iss-${++issueCounter}`;
 77→  return {
 78→    id,
 79→    title: `Issue ${id}`,
 80→    description: `Description for ${id}`,
 81→    trigger_mode: "event-based" as const,
 82→    auto_resolve_ms: 0,
 83→    lifecycle,
 84→    activated_at_pt_ms: 20_000,
 85→    resolved_at_pt_ms: lifecycle === "resolved" ? 50_000 : null,
 86→    released,
 87→  };
 88→});
 89→
 90→export const issuesArb = fc.array(issueArb, { maxLength: 2 });
 91→
 92→// ── Decisions ────────────────────────────────────────────────────────
 93→
 94→const OPTIONS = [
 95→  { id: "opt-a", label: "Option Alpha", score: 10 },
 96→  { id: "opt-b", label: "Option Beta", score: 5 },
 97→  { id: "opt-c", label: "Option Gamma", score: -2 },
 98→];
 99→
100→let decisionCounter = 0;
101→
102→const decisionArb = fc
103→  .record({
104→    target_roles: fc.subarray(["co", "nav", "ops"]),
105→    hasRecs: fc.boolean(),
106→  })
107→  .map(({ target_roles, hasRecs }) => {
108→    const id = `dec-${++decisionCounter}`;
109→    const recommendations: Record<string, string> = {};
110→    if (hasRecs) {
111→      recommendations["nav-advisor"] = "opt-a";
112→      recommendations["ops-advisor"] = "opt-b";
113→    }
114→    return {
115→      id,
116→      event_id: "e-1",
117→      issue_id: "iss-1",
118→      title: `Decision ${id}`,
119→      description: "Choose wisely.",
120→      question_type: "single_choice" as const,
121→      options: OPTIONS,
122→      completion_mode: "first_response" as const,
123→      target_roles,
124→      timeout_ms: 300_000,
125→      status: "open" as const,
126→      opened_at_pt_ms: 60_000,
127→      closed_at_pt_ms: null,
128→      recommendations,
129→    };
130→  });
131→
132→export const decisionsArb = fc.array(decisionArb, { maxLength: 1 });
133→
134→// ── Systems ──────────────────────────────────────────────────────────
135→
136→const SYSTEM_DEFS = [
137→  { system_id: "nav_radar", label: "NAV RADAR", category: "sensor" },
138→  { system_id: "comms", label: "COMMS", category: "system" },
139→  { system_id: "aaw_radar", label: "AAW RADAR", category: "sensor" },
140→  { system_id: "ew_suite", label: "EW SUITE", category: "system" },
141→];
142→
143→const systemArb = fc
144→  .record({
145→    idx: fc.integer({ min: 0, max: SYSTEM_DEFS.length - 1 }),
146→    power: fc.boolean(),
147→    operational: fc.constantFrom("green", "yellow", "red"),
148→  })
149→  .map(({ idx, power, operational }) => ({
150→    ...SYSTEM_DEFS[idx],
151→    power,
152→    operational,
153→  }));
154→
155→export const systemsArb = fc.array(systemArb, { maxLength: 4 });
156→
157→// ── Context ──────────────────────────────────────────────────────────
158→
159→const ROLES = [
160→  { id: "co", label: "Commanding Officer", player_type: "decision_maker" },
161→  { id: "nav", label: "Navigator", player_type: "advisor" },
162→  { id: "ops", label: "Operations", player_type: "advisor" },
163→];
164→
165→export const CONTEXT = {
166→  title: "Silent Wake",
167→  description: "Naval cyber exercise",
168→  briefing: "You are aboard the USS Sentinel.",
169→  objectives: ["Defend the ship", "Maintain comms"],
170→  rules: ["No external comms", "Time is critical"],
171→  roles: ROLES,
172→};
173→
174→// ── Composed state arbitrary ─────────────────────────────────────────
175→
