/**
 * Property-based Playwright tests for the player view.
 *
 * Uses fast-check to randomly generate valid player states and verify
 * that the 10 documented UI invariants hold across the full state space.
 * Existing hand-crafted tests in player-view-states.spec.ts remain as
 * pinned regression cases.
 */
import { test, expect } from "../fixtures/base.fixture";
import type { Page } from "@playwright/test";
import fc from "fast-check";
import {
  playerStateArb,
  buildSnapshot,
  buildPlayerUrl,
  CONTEXT,
  EX_ID,
  type PlayerState,
} from "../helpers/arbitraries";

const NUM_RUNS = Number(process.env["PROP_RUNS"] ?? 30);

// ── Mock installer (matches existing pattern) ────────────────────────

async function installMocks(
  page: Page,
  state: PlayerState,
): Promise<void> {
  const snap = buildSnapshot(state);
  const decisions = snap.decisions ?? [];

  await page.route(`**/api/exercises/${EX_ID}/engine/snapshot`, (route) =>
    route.fulfill({
      status: 200,
      contentType: "application/json",
      body: JSON.stringify(snap),
    }),
  );
  await page.route(`**/api/exercises/${EX_ID}/engine/context`, (route) =>
    route.fulfill({
      status: 200,
      contentType: "application/json",
      body: JSON.stringify(CONTEXT),
    }),
  );
  await page.route("**/api/decisions*", async (route) => {
    if (route.request().url().includes("/engine/")) {
      await route.fallback();
      return;
    }
    await route.fulfill({
      status: 200,
      contentType: "application/json",
      body: JSON.stringify([]),
    });
  });
  await page.route(
    `**/api/exercises/${EX_ID}/engine/decisions`,
    async (route) => {
      if (route.request().method() === "GET") {
        await route.fulfill({
          status: 200,
          contentType: "application/json",
          body: JSON.stringify(decisions),
        });
      } else {
        await route.fallback();
      }
    },
  );
  await page.route("**/ws?*", (route) => route.abort("connectionrefused"));
  await page.route("**/ws", (route) => route.abort("connectionrefused"));
  await page.route("**/api/domain-configs", (route) =>
    route.fulfill({
      status: 200,
      contentType: "application/json",
      body: JSON.stringify([]),
    }),
  );
}

