}

// ── Helpers ──────────────────────────────────────────────────────────

function isDecisionMakerRole(role: string): boolean {
  return role === "co";
}

function hasOpenDecisionForRole(state: PlayerState): boolean {
  if (state.decisions.length === 0) return false;
  const dec = state.decisions[0];
  if (dec.target_roles.length === 0) return true;
  return dec.target_roles.includes(state.role);
}

function hasRecommendations(state: PlayerState): boolean {
  if (state.decisions.length === 0) return false;
  return Object.keys(state.decisions[0].recommendations).length > 0;
}

function shouldShowScore(state: PlayerState): boolean {
  return state.score !== null && state.phase !== "briefing";
}

// ── Properties ──────────────────────────────────────────────────────

test.describe("Property: player view invariants @property", () => {
  test("P1: header always visible", async ({ page }) => {
    await fc.assert(
      fc.asyncProperty(playerStateArb, async (state) => {
        await installMocks(page, state);
        await page.goto(buildPlayerUrl(state));

        await expect(page.locator(".player-header__title")).toBeVisible();
        await expect(page.locator("tfc-phase-badge")).toBeVisible();
      }),
      { numRuns: NUM_RUNS },
    );
