        await page.goto(buildPlayerUrl(state));

        const banner = page.locator("tfc-turn-banner");
        if (shouldShowScore(state)) {
          await expect(banner).toBeVisible();
          await expect(banner).toContainText(`Turn ${state.score!.turn_number}`);
